#!/usr/bin/env node
// Generated by Keel — modern-web-guidance PostToolUse reminder hook.
// Reminds once per session, after the first UI file edit, to check modern web platform patterns.
// UI files: markup, styles and component files (.html .css .scss .sass .less .tsx .jsx .vue
// .svelte .astro). Plain .js/.ts/.mjs (backend, tests, config) never trigger it.
// The once-per-session marker lives in the OS temp folder, keyed by project path (never in the repo,
// so nothing to commit or gitignore); it holds the last session id and is safe to delete.
// No dependencies beyond Node.js built-ins.
// Self-test: node .claude/hooks/modern-web-guidance-hook.mjs --self-test
import { readFileSync, writeFileSync, mkdirSync, mkdtempSync } from 'fs'
import { spawnSync } from 'child_process'
import { tmpdir } from 'os'
import { join } from 'path'
import { createHash } from 'crypto'

if (process.argv[2] === '--self-test') {
  const cwd = mkdtempSync(join(tmpdir(), 'mwg-'))
  const run = (session, file) => spawnSync(process.execPath, [process.argv[1]], { cwd, encoding: 'utf8',
    input: JSON.stringify({ session_id: session, tool_input: { file_path: file } }) }).stdout
  const ok = (c, m) => { if (!c) { console.log('FAIL ' + m); process.exit(1) } }
  ok(run('s1', 'src/api/x.ts') === '', 'backend .ts must not remind')
  ok(run('s1', 'src/ui/A.tsx').includes('modern-web-guidance'), 'first UI edit reminds')
  ok(run('s1', 'src/ui/B.css') === '', 'second UI edit in the same session is silent')
  ok(run('s2', 'src/ui/B.css').includes('modern-web-guidance'), 'a new session reminds again')
  console.log('ok'); process.exit(0)
}

let input
try { input = JSON.parse(readFileSync('/dev/stdin', 'utf8')) } catch { process.exit(0) }

const filePath = input?.tool_input?.file_path || ''
const UI = /\.(html|css|scss|sass|less|tsx|jsx|vue|svelte|astro)$/i
if (!UI.test(filePath)) process.exit(0)

const marker = join(tmpdir(), 'keel-mwg-' + createHash('sha1').update(process.cwd()).digest('hex').slice(0, 12))
const session = String(input?.session_id || '')
let last = ''
try { last = readFileSync(marker, 'utf8').trim() } catch {}
if (session && last === session) process.exit(0)
try { writeFileSync(marker, session + '\n') } catch {}

process.stdout.write(
  '[modern-web-guidance] UI file touched: ' + filePath.split('/').pop() + ' (reminder shown once per session)\n' +
  'Before adding a new UI pattern: npx -y modern-web-guidance@latest search "<what you want to do>"\n' +
  'Prefer native: <dialog>, popover API, CSS scroll-driven animations, View Transitions API.\n'
)
process.exit(0)
